import {validateMessage} from './validation.js';

describe('list_sessions cursor [spec: specs/hal-engine-conversation-list/spec.md#39]', () => {
  it('preserves complete pagination cursors and rejects unusable cursor fields', () => {
    const cursors = [
      {sessionId: 's', updatedAt: '2026-01-01T00:00:00.000Z'},
      {sessionId: 's'.repeat(128), updatedAt: 0},
    ];
    const invalid = [
      null, [], 'cursor', {},
      {sessionId: '', updatedAt: 0},
      {sessionId: 's'.repeat(129), updatedAt: 0},
      {sessionId: 1, updatedAt: 0},
      {sessionId: 's'},
      {sessionId: 's', updatedAt: 'not a date'},
      {sessionId: 's', updatedAt: Infinity},
      {sessionId: 's', updatedAt: 1e20},
      {sessionId: 's', updatedAt: null},
      {sessionId: 's', updatedAt: true},
    ];

    expect({
      accepted: cursors.map(before => validateMessage({type: 'list_sessions', before: {...before, userId: 'other'}, userId: 'other'})),
      limited: validateMessage({type: 'list_sessions', limit: 2, before: cursors[0]}),
      rejected: invalid.map(before => validateMessage({type: 'list_sessions', before})),
    }).toEqual({
      accepted: cursors.map(before => ({valid: true, data: {type: 'list_sessions', before}})),
      limited: {valid: true, data: {type: 'list_sessions', limit: 2, before: cursors[0]}},
      rejected: invalid.map(() => ({valid: false, error: expect.stringContaining('before')})),
    });
  });
});
EOF
